package br.org.rosalina.social.student;
import br.org.rosalina.social.catalog.CatalogItem; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="socioeconomic_profile") public class SocioeconomicProfile {
 @Id @Column(name="student_id") private java.util.UUID id; @OneToOne @MapsId @JoinColumn(name="student_id") private Student student; @ManyToOne @JoinColumn(name="housing_type_id") private CatalogItem housingType; @ManyToOne @JoinColumn(name="acquisition_type_id") private CatalogItem acquisitionType; @ManyToOne @JoinColumn(name="wall_type_id") private CatalogItem wallType; @ManyToOne @JoinColumn(name="floor_type_id") private CatalogItem floorType; @Column(name="has_electricity") private Boolean hasElectricity; @ManyToOne @JoinColumn(name="water_supply_id") private CatalogItem waterSupply; @ManyToOne @JoinColumn(name="sewage_id") private CatalogItem sewage; @ManyToOne @JoinColumn(name="garbage_collection_id") private CatalogItem garbageCollection;
 @Column(name="water_expense") private BigDecimal waterExpense; @Column(name="electricity_expense") private BigDecimal electricityExpense; @Column(name="phone_expense") private BigDecimal phoneExpense; @Column(name="rent_or_financing_expense") private BigDecimal rentOrFinancingExpense; @Column(name="food_expense") private BigDecimal foodExpense; @Column(name="household_income") private BigDecimal householdIncome; @Column(name="has_other_assets") private Boolean hasOtherAssets; @Column(name="has_other_property") private Boolean hasOtherProperty; @Column(name="has_vehicle") private Boolean hasVehicle; @Column(name="receives_bolsa_familia") private Boolean receivesBolsaFamilia; @Column(name="receives_bpc") private Boolean receivesBpc; @Column(name="receives_retirement") private Boolean receivesRetirement;
 public void setStudent(Student v){student=v;} public CatalogItem getHousingType(){return housingType;} public CatalogItem getAcquisitionType(){return acquisitionType;} public CatalogItem getWallType(){return wallType;} public CatalogItem getFloorType(){return floorType;} public Boolean getHasElectricity(){return hasElectricity;} public CatalogItem getWaterSupply(){return waterSupply;} public CatalogItem getSewage(){return sewage;} public CatalogItem getGarbageCollection(){return garbageCollection;} public BigDecimal getWaterExpense(){return waterExpense;} public BigDecimal getElectricityExpense(){return electricityExpense;} public BigDecimal getPhoneExpense(){return phoneExpense;} public BigDecimal getRentOrFinancingExpense(){return rentOrFinancingExpense;} public BigDecimal getFoodExpense(){return foodExpense;} public BigDecimal getHouseholdIncome(){return householdIncome;} public Boolean getHasOtherAssets(){return hasOtherAssets;} public Boolean getHasOtherProperty(){return hasOtherProperty;} public Boolean getHasVehicle(){return hasVehicle;} public Boolean getReceivesBolsaFamilia(){return receivesBolsaFamilia;} public Boolean getReceivesBpc(){return receivesBpc;} public Boolean getReceivesRetirement(){return receivesRetirement;}
 public void setHousingType(CatalogItem v){housingType=v;} public void setAcquisitionType(CatalogItem v){acquisitionType=v;} public void setWallType(CatalogItem v){wallType=v;} public void setFloorType(CatalogItem v){floorType=v;} public void setHasElectricity(Boolean v){hasElectricity=v;} public void setWaterSupply(CatalogItem v){waterSupply=v;} public void setSewage(CatalogItem v){sewage=v;} public void setGarbageCollection(CatalogItem v){garbageCollection=v;} public void setWaterExpense(BigDecimal v){waterExpense=v;} public void setElectricityExpense(BigDecimal v){electricityExpense=v;} public void setPhoneExpense(BigDecimal v){phoneExpense=v;} public void setRentOrFinancingExpense(BigDecimal v){rentOrFinancingExpense=v;} public void setFoodExpense(BigDecimal v){foodExpense=v;} public void setHouseholdIncome(BigDecimal v){householdIncome=v;} public void setHasOtherAssets(Boolean v){hasOtherAssets=v;} public void setHasOtherProperty(Boolean v){hasOtherProperty=v;} public void setHasVehicle(Boolean v){hasVehicle=v;} public void setReceivesBolsaFamilia(Boolean v){receivesBolsaFamilia=v;} public void setReceivesBpc(Boolean v){receivesBpc=v;} public void setReceivesRetirement(Boolean v){receivesRetirement=v;}
}
